bench( format( '%s::complex128,typed_array,set', pkg ), function benchmark( b ) {
	var Complex128Array;
	var values;
	var arr;
	var buf;
	var M;
	var N;
	var v;
	var i;

	Complex128Array = factory( 'complex128' );

	values = new Float64Array( 20 );
	M = values.length;
	for ( i = 0; i < M; i++ ) {
		values[ i ] = i;
	}

	arr = new Complex128Array( values );
	N = arr.length;

	buf = new Float64Array( 2 );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		buf[ 0 ] = values[ i%N ];
		buf[ 1 ] = values[ (i+1)%N ];
		v = arr.set( buf );
		if ( typeof v !== 'undefined' ) {
			b.fail( 'should return undefined' );
		}
	}
	b.toc();
	if ( typeof v !== 'undefined' ) {
		b.fail( 'should return undefined' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::complex128,complex_typed_array,set', pkg ), function benchmark( b ) {
	var Complex128Array;
	var values;
	var arr;
	var buf;
	var M;
	var N;
	var v;
	var i;

	Complex128Array = factory( 'complex128' );

	values = new Float64Array( 20 );
	M = values.length;
	for ( i = 0; i < M; i++ ) {
		values[ i ] = i;
	}

	arr = new Complex128Array( values );
	N = arr.length;

	buf = new Complex128Array( 1 );
	buf.set( new Complex128( 1.0, -1.0 ) );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = arr.set( buf, i%N );
		if ( typeof v !== 'undefined' ) {
			b.fail( 'should return undefined' );
		}
	}
	b.toc();
	if ( typeof v !== 'undefined' ) {
		b.fail( 'should return undefined' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

